import{_ as i,o as t,c as n,a1 as o}from"./chunks/framework.COskihg7.js";const g=JSON.parse('{"title":"非 App 设备使用指南","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/non-app-devices.md","filePath":"zh/guide/non-app-devices.md"}'),l={name:"zh/guide/non-app-devices.md"};function s(e,a,r,d,h,p){return t(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="非-app-设备使用指南" tabindex="-1">非 App 设备使用指南 <a class="header-anchor" href="#非-app-设备使用指南" aria-label="Permalink to &quot;非 App 设备使用指南&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>无法安装 Android App 的设备（游戏主机、Mac、智能电视）仍然可以通过 <strong>Windows 网络连接共享 (ICS)</strong> 使用绕过后的网络连接。</p><p>搭建需要：</p><ol><li>一台运行 <strong>Host 模式</strong>的手机（热点源）</li><li>一台运行 <strong>Windows 客户端 VPN 模式</strong>的笔记本</li><li>目标设备连接到笔记本的移动热点</li></ol><hr><h2 id="连接示意" tabindex="-1">连接示意 <a class="header-anchor" href="#连接示意" aria-label="Permalink to &quot;连接示意&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[手机 (Host 模式)]</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>   Wi-Fi Direct</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>[Windows 笔记本 (VPN + 移动热点)]</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>   Wi-Fi 热点</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>[PS5 / Xbox / Switch / Mac / 电视]</span></span></code></pre></div><hr><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>已启动 <strong>Host 模式</strong>的手机</li><li>一台 <strong>Windows 笔记本</strong>（10 或 11，64 位，带 Wi-Fi）</li><li>需要联网的<strong>目标设备</strong></li></ul><hr><h2 id="分步设置" tabindex="-1">分步设置 <a class="header-anchor" href="#分步设置" aria-label="Permalink to &quot;分步设置&quot;">​</a></h2><h3 id="第一步-手机设置" tabindex="-1">第一步：手机设置 <a class="header-anchor" href="#第一步-手机设置" aria-label="Permalink to &quot;第一步：手机设置&quot;">​</a></h3><ol><li>打开手机应用。</li><li>切换到 <strong>HOST</strong> 标签。</li><li>点击<strong>启动 Host</strong>。</li><li>记录连接信息（SSID、密码、代理 IP、端口）。</li></ol><h3 id="第二步-笔记本设置" tabindex="-1">第二步：笔记本设置 <a class="header-anchor" href="#第二步-笔记本设置" aria-label="Permalink to &quot;第二步：笔记本设置&quot;">​</a></h3><ol><li>将笔记本连接到手机的 Wi-Fi Direct：<strong>DIRECT-HotspotBypass</strong>（密码：<code>87654321</code>）。</li><li>启动 <strong>Windows 客户端</strong>并开启 VPN（参见 <a href="/Hotspot-Bypass-VPN-Unlimited-Hotspot/zh/guide/windows">Windows 使用指南</a>）。</li><li>连接成功后，进入<strong>设置 → 网络和互联网 → 移动热点</strong>。</li><li>开启<strong>移动热点</strong>。</li></ol><h3 id="第三步-配置-ics" tabindex="-1">第三步：配置 ICS <a class="header-anchor" href="#第三步-配置-ics" aria-label="Permalink to &quot;第三步：配置 ICS&quot;">​</a></h3><ol><li>打开<strong>控制面板 → 网络和共享中心 → 更改适配器设置</strong>。</li><li>右键点击 <strong>LaptopProxyVPN</strong> TUN 网卡 → <strong>属性</strong>。</li><li>进入<strong>共享</strong>标签。</li><li>勾选<strong>允许其他网络用户通过此计算机的 Internet 连接来连接</strong>。</li><li>在下拉菜单中选择你的移动热点适配器（通常名称为&quot;本地连接* ##&quot;或类似）。</li><li>点击<strong>确定</strong>。</li></ol><h3 id="第四步-连接设备" tabindex="-1">第四步：连接设备 <a class="header-anchor" href="#第四步-连接设备" aria-label="Permalink to &quot;第四步：连接设备&quot;">​</a></h3><ol><li>在游戏主机 / Mac / 电视上打开 Wi-Fi 设置。</li><li>找到并连接到笔记本的移动热点网络。</li><li>设备现在应该可以通过绕过后的网络上网了。</li></ol><hr><h2 id="各设备说明" tabindex="-1">各设备说明 <a class="header-anchor" href="#各设备说明" aria-label="Permalink to &quot;各设备说明&quot;">​</a></h2><h3 id="playstation-5-playstation-4" tabindex="-1">PlayStation 5 / PlayStation 4 <a class="header-anchor" href="#playstation-5-playstation-4" aria-label="Permalink to &quot;PlayStation 5 / PlayStation 4&quot;">​</a></h3><ul><li>进入<strong>设置 → 网络 → 设定 → 设定互联网连接</strong></li><li>选择<strong>使用 Wi-Fi</strong> → 选中笔记本的热点</li><li>无需配置代理 — ICS 会自动处理</li><li>在<strong>设置 → 网络 → 连接状态</strong>中测试连接</li></ul><h3 id="xbox-series-x-s-xbox-one" tabindex="-1">Xbox Series X|S / Xbox One <a class="header-anchor" href="#xbox-series-x-s-xbox-one" aria-label="Permalink to &quot;Xbox Series X|S / Xbox One&quot;">​</a></h3><ul><li>进入<strong>设置 → 一般 → 网络设置 → 设置无线网络</strong></li><li>选择笔记本的热点</li><li>进入<strong>测试网络连接</strong>验证</li></ul><h3 id="nintendo-switch" tabindex="-1">Nintendo Switch <a class="header-anchor" href="#nintendo-switch" aria-label="Permalink to &quot;Nintendo Switch&quot;">​</a></h3><ul><li>进入<strong>系统设置 → 互联网 → 互联网设置</strong></li><li>选择笔记本的热点</li><li>测试连接</li></ul><h3 id="macbook" tabindex="-1">MacBook <a class="header-anchor" href="#macbook" aria-label="Permalink to &quot;MacBook&quot;">​</a></h3><ul><li>通过 Wi-Fi 连接到笔记本的热点</li><li>无需额外配置</li><li>适合游戏、浏览和流媒体</li></ul><h3 id="智能电视" tabindex="-1">智能电视 <a class="header-anchor" href="#智能电视" aria-label="Permalink to &quot;智能电视&quot;">​</a></h3><ul><li>打开<strong>网络设置</strong> → <strong>Wi-Fi</strong></li><li>选择笔记本的热点</li><li>适用于流媒体应用（Netflix、YouTube 等）和网页浏览</li></ul><hr><h2 id="性能提示" tabindex="-1">性能提示 <a class="header-anchor" href="#性能提示" aria-label="Permalink to &quot;性能提示&quot;">​</a></h2><ul><li><strong>5GHz 频段</strong> — 将手机设置为 5GHz Wi-Fi Direct 频段以获得更低延迟</li><li><strong>距离</strong> — 手机和笔记本保持在 10 米以内以获得最佳信号</li><li><strong>有线桥接</strong> — 如需最低延迟，可用网线将笔记本连接到主机而非 Wi-Fi 热点</li><li><strong>关闭其他应用</strong> — 减少手机上的带宽占用，提升游戏性能</li></ul><hr><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>解决方案</th></tr></thead><tbody><tr><td>设备可连接但无网络</td><td>检查 ICS 配置。重启移动热点。</td></tr><tr><td>高延迟 / 卡顿</td><td>将手机切换到 5GHz。缩短设备间距离。</td></tr><tr><td>热点未显示</td><td>确认笔记本支持 Windows 移动热点功能。</td></tr><tr><td>开启热点后 VPN 断开</td><td>部分 Wi-Fi 网卡无法同时处理两者。可尝试 USB Wi-Fi 网卡用作热点。</td></tr><tr><td>主机找不到热点</td><td>在 Windows 设置中将热点设为 2.4GHz 频段。</td></tr></tbody></table>`,39)])])}const u=i(l,[["render",s]]);export{g as __pageData,u as default};
